import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { AlreadyArchivedError } from "@/lib/soft-delete";
import { PermissionDeniedError, can } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as projectService from "@/server/services/project-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { OrgId, ProjectId, UserId } from "@/types/common";
import type { Actor } from "@/types/member";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

async function newUser(label: string): Promise<UserId> {
  const user = await userRepo.insertUser({
    email: `${label}@scratch.test`,
    name: label,
    passwordHash: "seed",
  });
  return user.id;
}

async function leadOf(tenant: Tenant, projectId: ProjectId = tenant.project.id) {
  return (await projectRepo.findProjectById(tenant.org.id, projectId))?.leadId;
}

describe("changeProjectLead (scratch)", () => {
  it("permission vocabulary: admin/owner, current lead, nobody else", async () => {
    const tenant = await createTenant("scratchperm", "growth");
    const resource = {
      kind: "project" as const,
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      visibility: "org" as const,
      leadId: tenant.userIds.owner,
    };
    expect(can(tenant.actors.owner, "project:change_lead", resource)).toBe(true);
    expect(can(tenant.actors.admin, "project:change_lead", resource)).toBe(true);
    expect(can(tenant.actors.member, "project:change_lead", resource)).toBe(false);
    expect(can(tenant.actors.viewer, "project:change_lead", resource)).toBe(false);
    const leadViewer: Actor = { ...tenant.actors.viewer };
    expect(
      can(leadViewer, "project:change_lead", { ...resource, leadId: leadViewer.userId }),
    ).toBe(true);
    expect(
      can(tenant.actors.member, "project:change_lead", {
        ...resource,
        leadId: tenant.userIds.member,
      }),
    ).toBe(true);
    expect(
      can(
        { ...tenant.actors.viewer, orgId: "01HZZZBBBBBBBBBBBBBBBBBBBB" as OrgId },
        "project:change_lead",
        { ...resource, leadId: tenant.userIds.viewer },
      ),
    ).toBe(false);
  });

  it("admin hands over to an active member; owner clears; lead hands over", async () => {
    const tenant = await createTenant("scratchok", "growth");
    const updated = await projectService.changeProjectLead(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      leadId: tenant.userIds.member,
    });
    expect(updated.leadId).toBe(tenant.userIds.member);
    expect(await leadOf(tenant)).toBe(tenant.userIds.member);

    // the current lead (a member) may hand it on without admin role
    const handedOn = await projectService.changeProjectLead(tenant.actors.member, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      leadId: tenant.userIds.owner,
    });
    expect(handedOn.leadId).toBe(tenant.userIds.owner);

    const cleared = await projectService.changeProjectLead(tenant.actors.owner, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      leadId: null,
    });
    expect(cleared.leadId).toBeNull();
    expect(await leadOf(tenant)).toBeNull();
  });

  it("a viewer who is the current lead may hand over; new lead must be able to update", async () => {
    const tenant = await createTenant("scratchviewerlead", "growth");
    await projectRepo.updateProject({
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      leadId: tenant.userIds.viewer,
    });
    const out = await projectService.changeProjectLead(tenant.actors.viewer, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      leadId: tenant.userIds.admin,
    });
    expect(out.leadId).toBe(tenant.userIds.admin);
  });

  it("rejects a non-lead member and a non-lead viewer, lead unchanged", async () => {
    const tenant = await createTenant("scratchdenied", "growth");
    for (const actor of [tenant.actors.member, tenant.actors.viewer]) {
      await expect(
        projectService.changeProjectLead(actor, {
          orgId: tenant.org.id,
          projectId: tenant.project.id,
          leadId: tenant.userIds.admin,
        }),
      ).rejects.toBeInstanceOf(PermissionDeniedError);
    }
    expect(await leadOf(tenant)).toBe(tenant.userIds.owner);
  });

  it("rejects a foreign orgId with the tenant-scope error", async () => {
    const tenant = await createTenant("scratchtenant", "growth");
    await expect(
      projectService.changeProjectLead(tenant.actors.owner, {
        orgId: "01HZZZBBBBBBBBBBBBBBBBBBBB" as OrgId,
        projectId: tenant.project.id,
        leadId: null,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("rejects another organization's project id with not-found", async () => {
    const tenantA = await createTenant("scratchxa", "growth");
    const tenantB = await createTenant("scratchxb", "growth");
    await expect(
      projectService.changeProjectLead(tenantA.actors.owner, {
        orgId: tenantA.org.id,
        projectId: tenantB.project.id,
        leadId: null,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    expect(await leadOf(tenantB)).toBe(tenantB.userIds.owner);
  });

  it("refuses an archived project with the already-archived error", async () => {
    const tenant = await createTenant("scratcharchived", "growth");
    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      archiveIssues: false,
    });
    await expect(
      projectService.changeProjectLead(tenant.actors.owner, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        leadId: null,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    expect(await leadOf(tenant)).toBe(tenant.userIds.owner);
  });

  it("rejects new leads who never joined, belong elsewhere, or were removed; lead unchanged", async () => {
    const tenant = await createTenant("scratchbadlead", "growth");
    const other = await createTenant("scratchbadother", "growth");

    const neverJoined = await newUser("never-joined");
    const otherOrgMember = other.userIds.member;
    const removedUser = await newUser("removed");
    const removed = await memberRepo.insertMember(tenant.org.id, removedUser, "member", null);
    await memberRepo.archiveMember(tenant.org.id, removed.id);

    for (const leadId of [neverJoined, otherOrgMember, removedUser]) {
      await expect(
        projectService.changeProjectLead(tenant.actors.owner, {
          orgId: tenant.org.id,
          projectId: tenant.project.id,
          leadId,
        }),
      ).rejects.toBeInstanceOf(NotFoundError);
    }
    expect(await leadOf(tenant)).toBe(tenant.userIds.owner);
  });

  it("rejects a viewer as the new lead with permission-denied; lead unchanged", async () => {
    const tenant = await createTenant("scratchviewerpick", "growth");
    await expect(
      projectService.changeProjectLead(tenant.actors.owner, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        leadId: tenant.userIds.viewer,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    expect(await leadOf(tenant)).toBe(tenant.userIds.owner);
  });

  it("uses the lead's org role, not platform staff status", async () => {
    const tenant = await createTenant("scratchstaff", "growth");
    const staffUser = await newUser("staff-lead");
    await memberRepo.insertMember(tenant.org.id, staffUser, "viewer", null);
    await expect(
      projectService.changeProjectLead(tenant.actors.owner, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        leadId: staffUser,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    expect(await leadOf(tenant)).toBe(tenant.userIds.owner);
  });
});

